      real(dp) :: wx0(20), wy0(20), wz0(20)
      real(dp) :: vAp(30)
      real(dp) :: vAm(9)
      real(dp) :: vBp(36)
      real(dp) :: vBm(6)
      real(dp) :: wxt(18), wyt(18), wzt(18)
      real(dp) :: f(0:BOYS_MMAX)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      rab2 = abx*abx + aby*aby + abz*abz

      ga = 0.0_dp; gb = 0.0_dp

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)*wt

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         vpref0 = 2.0_dp*PI/zeta*exp(-xi*rab2)

         do ic = 1, npt
            kk = k0 + (ic - 1)*kstep
            pcx = px - cpt(1, kk)
            pcy = py - cpt(2, kk)
            pcz = pz - cpt(3, kk)
            w2 = zk(kk)*zk(kk)
            theta = w2/(w2 + zeta)
            tval = theta*zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(4, tval, f)
            thm = 1.0_dp
