            vn(9,2) = pay*vn(4,2) - pcy*vn(4,3)
            vn(10,2) = paz*vn(4,2) - pcz*vn(4,3) &
               + 1.0_dp*oo2z*(vn(1,2) - vn(1,3))
            ! --- m = 1 ---
