            vn(11,1) = pax*vn(5,1) - pcx*vn(5,2) &
               + 2.0_dp*oo2z*(vn(2,1) - vn(2,2))
            vn(12,1) = pax*vn(6,1) - pcx*vn(6,2) &
               + 1.0_dp*oo2z*(vn(3,1) - vn(3,2))
            vn(13,1) = pax*vn(7,1) - pcx*vn(7,2) &
               + 1.0_dp*oo2z*(vn(4,1) - vn(4,2))
            vn(14,1) = pax*vn(8,1) - pcx*vn(8,2)
            vn(15,1) = pax*vn(9,1) - pcx*vn(9,2)
            vn(16,1) = pax*vn(10,1) - pcx*vn(10,2)
            vn(17,1) = pay*vn(8,1) - pcy*vn(8,2) &
